const TZS = new Intl.NumberFormat("en-TZ", { style: "currency", currency: "TZS", maximumFractionDigits: 0 });
const list = (query) => Array.isArray(query.data?.records) ? query.data.records : [];
const number = (value) => Number(value || 0);
const money = (value) => TZS.format(number(value));
const apiError = (error, fallback = "The School Management change could not be saved.") => error?.message || fallback;
const id = "__none__";

function Panel({ title, description, children, className = "" }) {
    return <section className={`sm-panel rounded-2xl p-5 ${className}`}>
<div className="mb-4"><h2 className="font-bold text-slate-900">{title}</h2>{description && <p className="mt-1 text-sm text-slate-500">{description}</p>}</div>{children}</section>;
}
function Field({ label, children, className = "" }) { return <label className={`grid gap-1.5 text-sm font-medium text-slate-700 ${className}`}><span>{label}</span>{children}</label>; }
function Input(props) { return <input {...props} className={`sm-control min-h-11 rounded-xl border border-slate-300 bg-white px-3 text-sm text-slate-900 outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-600/40 disabled:cursor-not-allowed disabled:bg-slate-100 ${props.className || ""}`} />; }
function Select(props) { return <select {...props} className={`sm-control min-h-11 rounded-xl border border-slate-300 bg-white px-3 text-sm text-slate-900 outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-600/40 disabled:cursor-not-allowed disabled:bg-slate-100 ${props.className || ""}`} />; }
function Textarea(props) { return <textarea {...props} className={`sm-control min-h-20 rounded-xl border border-slate-300 bg-white p-3 text-sm text-slate-900 outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-600/40 disabled:cursor-not-allowed disabled:bg-slate-100 ${props.className || ""}`} />; }
function Button({ children, variant = "primary", className = "", ...props }) { const colors = variant === "primary" ? "bg-indigo-700 text-white hover:bg-indigo-800" : variant === "danger" ? "bg-rose-600 text-white hover:bg-rose-700" : "border border-slate-300 bg-white text-slate-700 hover:bg-slate-50"; return <button type={props.type || "button"} {...props} className={`inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-3 text-sm font-semibold transition active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50 aria-busy:cursor-wait aria-busy:pointer-events-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-600/40 ${colors} ${className}`}>{children}</button>; }
function Notice({ children }) { return <p className="rounded-xl border border-dashed border-slate-200 bg-slate-50 p-4 text-sm text-slate-500">{children}</p>; }
function Denied({ children }) { return <p className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><strong>Restricted action.</strong> {children}</p>; }
function Loading() { return <div className="flex items-center gap-2 py-4 text-sm text-slate-500"><LoaderCircle size={16} className="animate-spin" /> Loading secure school records…</div>; }
function Status({ value }) { const text = String(value || "Unknown"); const color = /active|approved|paid|published|recorded|present|submitted|sent/i.test(text) ? "bg-emerald-50 text-emerald-700" : /rejected|absent|archived|critical/i.test(text) ? "bg-rose-50 text-rose-700" : "bg-amber-50 text-amber-800"; return <span role="status" className={`inline-flex items-center rounded-full px-2.5 py-1 text-xs font-semibold ${color}`}><span className="mr-1.5 h-1.5 w-1.5 rounded-full bg-current" aria-hidden="true" />{text}</span>; }
function Table({ children }) { return <div className="sm-responsive-table overflow-x-auto" tabIndex={0} aria-label="Scrollable school records table"><table className="w-full min-w-[690px] text-left text-sm">{children}</table></div>; }
function Options({ items, label = "Select record" }) { return <><option value={id}>{label}</option>{items.map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</>; }

function SchoolDocumentManager({ admissions, students, reportCards, disciplineRecords, canUpload }) {
  const [ownerType, setOwnerType] = useState("Student");
  const [ownerId, setOwnerId] = useState(id);
  const [portalVisible, setPortalVisible] = useState(false);
  const [file, setFile] = useState(null);
  const utils = trpc.useUtils();
  const upload = trpc.school.uploadDocument.useMutation();
  const owners = ownerType === "Admission" ? admissions : ownerType === "Student" ? students : ownerType === "Report card" ? reportCards : ownerType === "Discipline" ? disciplineRecords : [];

  async function submit(event) {
    event.preventDefault();
    if (!file) { toast.error("Choose a school document before uploading."); return; }
    if (file.size > 6 * 1024 * 1024) { toast.error("School documents must be 6 MB or smaller."); return; }
    const allowed = ["application/pdf", "image/jpeg", "image/png", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "text/csv"];
    if (!allowed.includes(file.type)) { toast.error("Use a PDF, JPEG, PNG, DOCX, or CSV school document."); return; }
    try {
      const buffer = await file.arrayBuffer();
      const bytes = new Uint8Array(buffer);
      let binary = "";
      const sliceSize = 32_768;
      for (let index = 0; index < bytes.length; index += sliceSize) binary += String.fromCharCode(...bytes.subarray(index, Math.min(index + sliceSize, bytes.length)));
      await upload.mutateAsync({ ownerType, ownerId, fileName: file.name, mimeType: file.type, access: portalVisible ? "Portal visible" : "Restricted", base64: btoa(binary) });
      toast.success("School document uploaded and registered.");
      setFile(null);
      await utils.school.list.invalidate();
    } catch (error) { toast.error(apiError(error, "The school document could not be uploaded.")); }
  }

  return <Panel title="Secure school documents" description="Files are stored through the project’s protected storage boundary. Record metadata, ownership, and portal visibility remain tenant scoped.">{!canUpload ? <Denied>Your role cannot upload School Management documents.</Denied> : <form className="grid gap-3 md:grid-cols-2" onSubmit={submit}><Field label="Record type"><Select value={ownerType} onChange={(event) => { setOwnerType(event.target.value); setOwnerId(id); }}>{["Student", "Admission", "Report card", "Discipline"].map((item) => <option key={item}>{item}</option>)}</Select></Field><Field label="Record"><Select required value={ownerId} onChange={(event) => setOwnerId(event.target.value)}><Options items={owners} label={`Select ${ownerType.toLowerCase()} record`} /></Select></Field><Field label="Document" className="md:col-span-2"><Input required type="file" accept="application/pdf,image/jpeg,image/png,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/csv" onChange={(event) => setFile(event.target.files?.[0] || null)} /></Field><label className="flex items-center gap-2 text-sm font-semibold text-slate-700 md:col-span-2"><input type="checkbox" checked={portalVisible} onChange={(event) => setPortalVisible(event.target.checked)} /> Permit authorised portal access to this document</label><div className="md:col-span-2"><Button type="submit" disabled={upload.isPending || ownerId === id}><FileText size={16} /> Upload document</Button></div></form>}</Panel>;
}

function SchoolServiceWelfareManager() {
  const [allocation, setAllocation] = useState({ table: "sch_transport_assignments", studentId: id, serviceId: id, termId: id });
  const [discipline, setDiscipline] = useState({ studentId: id, incidentDate: new Date().toISOString().slice(0, 10), category: "", severity: "Medium", description: "", actionTaken: "" });
  const accessQuery = trpc.school.access.useQuery(undefined, { retry: false });
  const studentsQuery = trpc.school.list.useQuery({ table: "sch_students", limit: 500 }, { retry: false });
  const termsQuery = trpc.school.list.useQuery({ table: "sch_terms", limit: 250 }, { retry: false });
  const transportQuery = trpc.school.list.useQuery({ table: "sch_transport", limit: 500 }, { retry: false });
  const hostelsQuery = trpc.school.list.useQuery({ table: "sch_hostels", limit: 500 }, { retry: false });
  const disciplineQuery = trpc.school.list.useQuery({ table: "sch_disciplinary_records", limit: 500 }, { retry: false });
  const serviceAssign = trpc.school.assignService.useMutation();
  const disciplineCreate = trpc.school.createDisciplineRecord.useMutation();
  const utils = trpc.useUtils();
  const access = accessQuery.data || {};
  const students = list(studentsQuery);
  const terms = list(termsQuery);
  const services = allocation.table === "sch_transport_assignments" ? list(transportQuery) : list(hostelsQuery);
  const disciplineRecords = list(disciplineQuery);
  async function run(action, success) { try { await action(); toast.success(success); await utils.school.list.invalidate(); } catch (error) { toast.error(apiError(error)); } }

  return <div className="grid gap-5 xl:grid-cols-2"><Panel title="Assign transport or hostel" description="A protected allocation links an enrolled learner to a real tenant-scoped transport route or hostel.">{!access.canManageServices ? <Denied>Your role cannot allocate transport or hostel services.</Denied> : <form className="grid gap-3 md:grid-cols-2" onSubmit={(event) => { event.preventDefault(); run(() => serviceAssign.mutateAsync({ table: allocation.table, studentId: allocation.studentId, serviceId: allocation.serviceId, termId: allocation.termId === id ? undefined : allocation.termId, notes: "" }), "Student service allocation saved."); }}><Field label="Allocation type"><Select value={allocation.table} onChange={(event) => setAllocation({ ...allocation, table: event.target.value, serviceId: id })}><option value="sch_transport_assignments">Transport route</option><option value="sch_hostel_allocations">Hostel</option></Select></Field><Field label="Student"><Select required value={allocation.studentId} onChange={(event) => setAllocation({ ...allocation, studentId: event.target.value })}><Options items={students} label="Select student" /></Select></Field><Field label="Service"><Select required value={allocation.serviceId} onChange={(event) => setAllocation({ ...allocation, serviceId: event.target.value })}><Options items={services} label={allocation.table === "sch_transport_assignments" ? "Select transport route" : "Select hostel"} /></Select></Field><Field label="Term"><Select value={allocation.termId} onChange={(event) => setAllocation({ ...allocation, termId: event.target.value })}><Options items={terms} label="No term" /></Select></Field><div className="md:col-span-2"><Button type="submit" disabled={serviceAssign.isPending}><Bus size={16} /> Save allocation</Button></div></form>}</Panel><Panel title="Disciplinary record" description="Student welfare records are protected operational data with verified learner ownership and auditable action detail.">{!access.canManageWelfare ? <Denied>Your role cannot create disciplinary records.</Denied> : <form className="grid gap-3 md:grid-cols-2" onSubmit={(event) => { event.preventDefault(); run(() => disciplineCreate.mutateAsync(discipline), "Disciplinary record created."); setDiscipline({ studentId: id, incidentDate: new Date().toISOString().slice(0, 10), category: "", severity: "Medium", description: "", actionTaken: "" }); }}><Field label="Student"><Select required value={discipline.studentId} onChange={(event) => setDiscipline({ ...discipline, studentId: event.target.value })}><Options items={students} label="Select student" /></Select></Field><Field label="Incident date"><Input required type="date" value={discipline.incidentDate} onChange={(event) => setDiscipline({ ...discipline, incidentDate: event.target.value })} /></Field><Field label="Category"><Input required value={discipline.category} onChange={(event) => setDiscipline({ ...discipline, category: event.target.value })} /></Field><Field label="Severity"><Select value={discipline.severity} onChange={(event) => setDiscipline({ ...discipline, severity: event.target.value })}>{["Low", "Medium", "High", "Critical"].map((item) => <option key={item}>{item}</option>)}</Select></Field><Field label="Incident details" className="md:col-span-2"><Textarea required value={discipline.description} onChange={(event) => setDiscipline({ ...discipline, description: event.target.value })} /></Field><Field label="Action taken" className="md:col-span-2"><Textarea value={discipline.actionTaken} onChange={(event) => setDiscipline({ ...discipline, actionTaken: event.target.value })} /></Field><div className="md:col-span-2"><Button type="submit" disabled={disciplineCreate.isPending}><ClipboardCheck size={16} /> Save welfare record</Button></div></form>}<div className="mt-4 border-t border-slate-100 pt-3">{disciplineRecords.length ? disciplineRecords.slice(0, 5).map((record) => <div key={record.id} className="mb-2 rounded-lg bg-slate-50 p-3 text-sm"><p className="font-semibold">{record.name}</p><Status value={record.severity || record.status} /></div>) : <Notice>No disciplinary records have been recorded.</Notice>}</div></Panel></div>;
}

function SchoolPortalView() {
  const portal = trpc.school.portal.useQuery(undefined, { retry: false });
  if (portal.isLoading) return <div className="grid min-h-72 place-items-center rounded-2xl border bg-white"><LoaderCircle className="animate-spin text-indigo-600" /></div>;
  if (portal.error) return <div className="rounded-2xl border border-rose-200 bg-rose-50 p-5 text-sm text-rose-800"><strong>Your School Portal is unavailable.</strong> No school data was changed. {portal.error.message}</div>;
  const data = portal.data;
  const invoices = Array.isArray(data.invoices) ? data.invoices : [];
  const reports = Array.isArray(data.reports) ? data.reports : [];
  const attendance = Array.isArray(data.attendance) ? data.attendance : [];
  const assignments = Array.isArray(data.assignments) ? data.assignments : [];
  const announcements = Array.isArray(data.announcements) ? data.announcements : [];
  const messages = Array.isArray(data.messages) ? data.messages : [];
  const students = Array.isArray(data.students) ? data.students : [];
  const teachers = Array.isArray(data.teachers) ? data.teachers : [];
  const linked = [...students.map((record) => record.name), ...teachers.map((record) => record.name)];
  return <div className="space-y-5"><section className="rounded-3xl bg-gradient-to-br from-indigo-950 via-indigo-800 to-sky-700 p-6 text-white shadow-lg"><div className="flex items-start gap-3"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-white/15"><GraduationCap /></span><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-indigo-100">Linked school account</p><h1 className="mt-1 text-2xl font-bold">School Portal</h1><p className="mt-2 text-sm text-indigo-50">View only the records specifically linked to your verified workspace profile. {linked.length ? `Linked profile: ${linked.join(", ")}.` : "No active school profile is linked yet."}</p></div></div></section><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article className="rounded-2xl border border-slate-200 bg-white p-4"><Users className="text-indigo-600" size={19} /><p className="mt-3 text-2xl font-bold text-slate-900">{linked.length}</p><p className="text-xs font-semibold text-slate-500">Linked profiles</p></article><article className="rounded-2xl border border-slate-200 bg-white p-4"><ReceiptText className="text-indigo-600" size={19} /><p className="mt-3 text-2xl font-bold text-slate-900">{invoices.filter((record) => record.status !== "Paid").length}</p><p className="text-xs font-semibold text-slate-500">Open invoices</p></article><article className="rounded-2xl border border-slate-200 bg-white p-4"><FileText className="text-indigo-600" size={19} /><p className="mt-3 text-2xl font-bold text-slate-900">{reports.length}</p><p className="text-xs font-semibold text-slate-500">Published reports</p></article><article className="rounded-2xl border border-slate-200 bg-white p-4"><ClipboardList className="text-indigo-600" size={19} /><p className="mt-3 text-2xl font-bold text-slate-900">{assignments.length}</p><p className="text-xs font-semibold text-slate-500">Class assignments</p></article></section><section className="grid gap-5 xl:grid-cols-2"><Panel title="Fee and report-card records" description="Portal-visible school finance and academic outcomes are supplied by the protected server linkage."><div className="space-y-3">{invoices.map((record) => <div key={record.id} className="rounded-xl bg-slate-50 p-3"><div className="flex justify-between gap-3"><p className="font-semibold">{record.invoiceNo || record.name}</p><Status value={record.status} /></div><p className="mt-1 text-sm text-slate-700">{record.termName || "Term"} · Total {money(record.amount)} · Balance {money(record.balance)}</p></div>)}{reports.map((record) => <div key={record.id} className="rounded-xl bg-indigo-50 p-3"><div className="flex justify-between gap-3"><p className="font-semibold">{record.termName || record.name}</p><Status value={record.status} /></div><p className="mt-1 text-sm text-slate-700">Average {number(record.average).toFixed(1)}% · Grade {record.grade || "—"}</p></div>)}{!invoices.length && !reports.length && <Notice>No portal-visible invoices or report cards are available.</Notice>}</div></Panel><Panel title="Attendance and assignments" description="Attendance and assignment records are filtered to the linked learner’s active class."><div className="space-y-3">{attendance.slice(0, 10).map((record) => <div key={record.id} className="flex items-center justify-between rounded-xl bg-slate-50 p-3"><p className="text-sm font-semibold">Attendance record</p><Status value={record.status} /></div>)}{assignments.map((record) => <div key={record.id} className="rounded-xl bg-indigo-50 p-3"><p className="font-semibold">{record.name}</p><p className="mt-1 text-sm text-slate-700">Due {record.dueAt ? new Date(record.dueAt).toLocaleString("en-TZ") : "Not specified"}</p></div>)}{!attendance.length && !assignments.length && <Notice>No portal-visible attendance or assignments are available.</Notice>}</div></Panel></section><section className="grid gap-5 xl:grid-cols-2"><Panel title="School announcements" description="Only messages published to the linked portal audience or class appear here."><div className="space-y-3">{announcements.map((record) => <article key={record.id} className="rounded-xl bg-indigo-50 p-3"><p className="font-semibold">{record.name}</p><p className="mt-1 text-sm text-slate-700">{record.notes}</p></article>)}{!announcements.length && <Notice>No announcements are available.</Notice>}</div></Panel><Panel title="Messages" description="Only messages delivered to your verified profile or linked class appear here."><div className="space-y-3">{messages.map((record) => <article key={record.id} className="rounded-xl bg-slate-50 p-3"><div className="flex justify-between gap-3"><p className="font-semibold">{record.name}</p><Status value={record.status} /></div><p className="mt-1 text-sm text-slate-700">{record.notes}</p></article>)}{!messages.length && <Notice>No messages are available.</Notice>}</div></Panel></section></div>;
}

function SchoolNotificationCenter() {
  const notifications = trpc.school.list.useQuery({ table: "sch_notifications", limit: 50 }, { retry: false });
  const markRead = trpc.school.markNotificationRead.useMutation();
  const utils = trpc.useUtils();
  const records = list(notifications);
  const unread = records.filter((record) => record.status === "Unread");
  if (notifications.isLoading || !records.length) return null;
  return <Panel title="School notifications" description="Operational alerts are scoped to the active tenant and may be marked read without changing their audit history."><div className="flex flex-wrap gap-3"><p className="rounded-full bg-amber-50 px-3 py-2 text-sm font-semibold text-amber-900">{unread.length} unread</p>{unread.slice(0, 4).map((record) => <div key={record.id} className="flex min-w-64 flex-1 items-center justify-between gap-3 rounded-xl bg-slate-50 p-3"><div><p className="font-semibold text-slate-900">{record.name}</p><p className="text-xs text-slate-600">{record.notes}</p></div><Button variant="secondary" disabled={markRead.isPending} onClick={async () => { try { await markRead.mutateAsync({ notificationId: record.id }); toast.success("School notification marked read."); await utils.school.list.invalidate(); } catch (error) { toast.error(apiError(error)); } }}>Mark read</Button></div>)}</div></Panel>;
}

